def convert_binary_tree_to_double_linked_list(root):
  '''Function to convert a binary tree into a doubly-linked list.'''
  if root is None:
    return None

  current_node = root
  heads = []

  while current_node is not None:
    if current_node.left is not None:
      previous_node = current_node.left
      while previous_node.right is not None and previous_node.right != current_node:
        previous_node = previous_node.right

      if previous_node.right is None:
        previous_node.right = current_node
        current_node = current_node.left
      else:
        previous_node.right = None
        heads.append(current_node)
        current_node = current_node.right
    else:
      heads.append(current_node)
      current_node = current_node.right

  for index in range(1, len(heads)):
    heads[index-1].right = heads[index]
    heads[index].left = heads[index-1]

  return heads[0]

