def solve_puzzle(puzzle):
    row_length = len(puzzle[0])
    col_length = len(puzzle)
    visited = [[False]*row_length for i in range(col_length)] 
    res = 0
    for row in range(col_length): 
        for col in range(row_length): 
            if visited[row][col] == False:
                explored_count = DFS(row, col, puzzle, visited, row_length, col_length)
                if explored_count > res: 
                    res = explored_count 
    return res 

def DFS(row, col, puzzle, visited, row_length, col_length): 
    visited[row][col] = True
    count = 1
    for r in range(row-1, row+2): 
        for c in range(col-1, col+2):
            if (r >= 0 and c >= 0 and r<col_length and c<row_length 
                and not visited[r][c] and puzzle[r][c] == puzzle[row][col]): 
                count += DFS(r, c, puzzle, visited, row_length, col_length) 
    return count

