public class LongestIncreasingSubsequence {

 public static int getLIS(int[] arr) {
    // base cases
    if (arr.length == 0) return 0;
    if (arr.length == 1) return 1;

    // stores the length of the longest increasing subsequence
    int lisCount = 1;

    // stores the maximum lis until ith index
    int[] memo = new int[arr.length];

    // initialize memo[i] as 1
    for (int i = 0; i < arr.length; i++)
        memo[i] = 1;

    // compute maximum lis of all i
    for (int i = 1; i < arr.length; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[i] > arr[j] && memo[i] < memo[j] + 1)
                memo[i] = memo[j] + 1;
        }

        // updating maximum length of lis found
        if (lisCount < memo[i])
            lisCount = memo[i];
    }

    return lisCount;
 }

 public static void main(String[] args) {
    int[] arr = {3, 4, 2, 1, 5, 7};
    System.out.println(getLIS(arr)); // 4
 }
}

