    public static void main(String[] args) {
        String str = "abbacccabbabbabbabbacccabbabbc";
        int n = str.length();

        int dp[][] = new int[n][n];

        int res_len = 0; // To store length of result
        int res_index = 0; // To store index of result

        for (int i = 0; i < n; i++) 
        { 
            for (int j = i + 1; j < n; j++) 
            { 

                if (j == i + 1) 
                    dp[i][j] = (str.charAt(i) == str.charAt(j)) ? 2 : 0;

