                    dp[i][j] = (str.charAt(i) == str.charAt(j)) ?  
                                            dp[i + 1][j - 1] + 2 : 
                                            Math.max(dp[i][j - 1], dp[i + 1][j]);

                if (dp[i][j] > res_len)
                {
                    res_len = dp[i][j]; 
                    res_index = Math.max(i, res_index);
                }
            }
        }

