def hamming_code(message): 
    # Pad the message with zeros until it is a multiple of 4
    while (len(message) % 4 != 0): 
        message += "0"

    # Split the message into 4-bit chunks 
    message_chunks = [message[i:i+4] for i in range(0, len(message), 4)] 

    # Calculate parity bits
    parity_bits = []

    for chunk in message_chunks:
        # Check for even number of ones in the chunk
        ones_count = 0
        for bit in chunk:
            if bit == '1':
                ones_count += 1
        if ones_count % 2 == 0:
            parity_bits.append('0')
        else:
            parity_bits.append('1')

    # Combine the message and parity bits
    encoded_message = ""
    for i in range(len(message_chunks)):
        encoded_message += message_chunks[i] + parity_bits[i]

    return encoded_message

