def longestCommonSubstring(string1, string2):
    m = len(string1) 
    n = len(string2)
    # Create a 2D array to store the results
    L = [[0] * (n+1) for _ in range(m+1)]

    result = 0
    for i in range(1, m+1):
        for j in range(1, n+1):
            if string1[i-1] == string2[j-1]: 
                L[i][j] = 1 + L[i - 1][j - 1]
                result = max(result, L[i][j]) 
            else:
                L[i][j] = 0

