def nearest_prime(num):
  # check if the number is less than 2
  if num < 2:
    return None

  # check if the number is 2 or 3, as these two numbers are both prime
  elif num == 2 or num == 3:
    return num

  # check if the number is prime
  is_prime = True
  for i in range(2, int(num**0.5) + 1):
      if num % i == 0:
          is_prime = False
          break

  if is_prime:
    return num

  # check if the number's predecessor is prime
  if is_prime(num - 1):
      return num - 1

  # check if the next number is prime
  if is_prime(num + 1):
      return num + 1

