function binary_search(arr, key){
    var start=0;
    var end=arr.length-1;

    while(start<=end){
        var mid=Math.floor((start+end)/2);
        if(arr[mid]===key){
            return mid;
        }
        else if(arr[mid]<key){
            start=mid+1;
        }
        else{
            end=mid-1;
        }
    }
    return -1;
}

// Function to optimize array 
function optArray(arr, target) {
  const sorted = arr.sort((a,b) => a-b);  // sort the array in ascending order

  let curSum = 0;  // set current sum 
  for (let i = 0; i < arr.length; i++) { 
    const diff = target - curSum;
    let curVal = sorted[i];
    // if the difference between the target and
    // current sum is less than the current value
    // then subtract the diff from the
    // current value
    if (diff < curVal) {
        curVal = diff;
    }
    // set current sum
    curSum += curVal;
    // update the array with current value
    sorted[i] = curVal;
  }
  return sorted;
}

