def spellChecker(word): 

    # Create a list of words in the dictionary 
    dict_words = ["Apple", "Mango", "Banana"]

    # If the word is in dictionary, then return the corrected word 
    if word in dict_words: 
        return word  
    else: 
        # Find the smallest edit distance (requires one character additions/deletions/substitutions) 
        min_dist = float("inf") 
        for dict_word in dict_words: 
            dist = editDistance(word, dict_word) 
            if dist < min_dist: 
                min_dist = dist 
                correct_word = dict_word 
        return correct_word 

def editDistance(word1, word2): 
    # Initialize the matrix with -1's 
    matrix = [] 
    for i in range(len(word1) + 1): 
        row = [] 
        for j in range(len(word2) + 1): 
            row.append(-1) 
        matrix.append(row) 

    # Set up base cases 
    for i in range(len(word1) + 1): 
        matrix[i][0] = i 
    for j in range(len(word2) + 1): 
        matrix[0][j] = j 

    # Compute edit distance 
    for i in range(1, len(word1) + 1): 
        for j in range(1, len(word2) + 1): 
            if word1[i - 1] == word2[j - 1]: 
                matrix[i][j] = matrix[i - 1][j - 1] 
            else: 
                matrix[i][j] = 1 + min(matrix[i][j - 1],  
                                       matrix[i - 1][j],  
                                       matrix[i - 1][j - 1]) 

    return matrix[len(word1)][len(word2)]

