def rearrange_list(lst):
    """
    Rearranges an array of numbers such that the smallest numbers come first
    """
    n = len(lst)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if lst[min_idx] > lst[j]:
                min_idx = j 

        lst[i], lst[min_idx] = lst[min_idx], lst[i]

    return lst

