"""
Write a code to detect near duplicate passages in a text
"""

def tokenize_text(text):
    # Break the text into tokens
    tokens = text.split()
    return tokens

def detect_duplicates(text):
    tokens = tokenize_text(text)
    # Find near duplicates by comparing each token with the remaining tokens
    duplicates = set()
    num_tokens = len(tokens)
    for i in range(num_tokens):
        for j in range(i+1, num_tokens):
            if tokens[i] == tokens[j]:
                duplicates.add(tokens[i])
    return duplicates

