def compress_string(string):
    result = ""

    count = 1
    prev_char = None

    for char in string:
        # if there is a new character, add it and its count to the result
        if prev_char != char:
            if prev_char:
                result += prev_char + str(count)
            prev_char = char
            count = 1
        # if it is the same character, just increment the count
        else:
            count += 1

    result += prev_char + str(count)

