def leastCommonElement(arr):
    # Create a frequency map
    freqMap = {}
    for num in arr:
        if num in freqMap:
            freqMap[num] += 1
        else:
            freqMap[num] = 1

    # Find the least common element
    leastCommon = None
    minCount = float('inf')
    for num, count in freqMap.items():
        if count < minCount:
            leastCommon = num
            minCount = count

    return leastCommon

