def depth_first_traversal(root):
    if root is None:
        return

    visited_list = []
    stack = [root]

    while stack:
        curr_node = stack.pop()
        visited_list.append(curr_node.value)

        if curr_node.right:
            stack.append(curr_node.right)

        if curr_node.left:
