 def make_move(self):
  best_score = -1000
  best_move = None

  for col in range(self.board.width):
   row = 0
   while row < self.board.height and self.board.grid[row][col] == '.':
    row += 1

   tmp_board = copy.deepcopy(self.board)
   tmp_board.add_piece(row - 1, col, self.piece) 
   score = self.minmax(tmp_board, depth-1, False) 
   if score > best_score:
    best_score = score 
    best_move = col

  self.board.add_piece(row - 1, best_move, self.piece)

 @staticmethod
 def minmax(board, depth, isMaximizing):
  if board.check_win():
    if board.current_turn == self.piece:
     return 1 # Win
    else:
     return -1 # Loss

  if depth == 0:
   return 0

  best_score = -1000 if isMaximizing else 1000
  for col in range(board.width):
   row = 0
   while row < board.height and board.grid[row][col] == '.':
    row += 1

   tmp_board = copy.deepcopy(board)
   tmp_board.add_piece(row - 1, col, board.current_turn) 
   score = self.minmax(tmp_board, depth-1, not isMaximizing) 
   if isMaximizing:
    best_score = max(score, best_score)
   else: 
    best_score = min(score, best_score) 

  return best_score

