// Function to convert a given IP address into its dotted decimal notation
function convertIPToDottedDecimal(ip) {
 // convert the given IP address to its decimal notation
 let decimal = 0;
 let parts = ip.split('.');

 // loop over the parts of the given IP address
 for (let i = 0; i < parts.length; i++) {
 decimal += (parts[i] * (256 ** (3 - i)));
 }

 // convert the decimal back to its dotted decimal notation
 let dottedDecimal = '';
 for (let j = 0; j < 4; j++) {
 let power = 3 - j;
 dottedDecimal += Math.floor(decimal / (256 ** power));
 // subtract the decimal value of the current part
 decimal -= (Math.floor(decimal / (256 ** power)) * (256 ** power));
 // add a dot if necessary
 if (j !== 3) {
 dottedDecimal += '.';
 }
 }

 return dottedDecimal;
}

