def compress_string(string):
    """Compresses a string by replacing consecutive characters by a single character and its count"""
    result = ''
    prev_char = ''
    char_count = 0
    for char in string:
        if char == prev_char:
            char_count += 1
        else:
            if prev_char != '':
                result += prev_char + str(char_count)
            prev_char = char
            char_count = 1
    result += prev_char + str(char_count)
    return result

def memodecorator(func):
    cache = {}
    def decorated_func(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    return decorated_func

