def find_all_anagrams(given_string, list_of_strings):
  # Create a dictionary out of the given string 
  dict = {}
  for char in given_string:
    if char in dict:
      dict[char] += 1
    else:
      dict[char] = 1

  # Iterate over the list of strings
  anagrams = []
  for string in list_of_strings:
    # Create a dictionary out of the string
    temp_dict = {}
    for char in string:
      if char not in dict:
        break
      elif char in temp_dict:
        temp_dict[char] += 1
      else:
        temp_dict[char] = 1

    # Check if the dictionaries match
    if temp_dict == dict:
      anagrams.append(string)

