// Step 1: Declare a function with signature string intToString(int num) 

// Step 2: Declare an empty string and assign it to a variable result 

// Step 3: If the parameter num is 0 then assign '0' to the result string

// Step 4: Else use a while loop that iterates until num has been decreased to 0. 

// Step 4a: Each loop iteration add the corresponding character of the number to the result string 

// Step 4b: Update the value of num by dividing it with 10

// Step 5: Return the result string

// Function Implementation 
string intToString(int num) {
 string result = ""; 

 if (num == 0) 
  result += '0'; 
 else { 
  while(num > 0) 
  { 
   result += (num % 10 + '0'); 
   num = num / 10; 
  } 
 } 

 return result; 
}

