public static int longestIncreasingSubsequenceLength(int[] list) {
	// Initialize the array to store the length of the longest increasing subsequence
	int[] lis = new int[list.length];

	// Initialize the lis with all 1s
	Arrays.fill(lis, 1);

	// Iterate through the list 
	for (int i = 1; i < list.length; i++) {
		// Iterate through all the elements before the current one
		for (int j = 0; j < i; j++) {
			// Check if the current element is larger than the list before it 
			if (list[i] > list[j] && lis[i] < lis[j] + 1) 
