class Node { 
    int key; 
    Node left, right;

    public Node(int item) { 
        this.key = item; 
        left = right = null; 
    }
} 

class BinarySearchTree { 

    Node root; 

    BinarySearchTree() { 
        root = null; 
    } 

    //Insert a new node
    void insert(int key) { 
        root = insertRec(root, key); 
    } 

    Node insertRec(Node root, int key) { 

        /* If the tree is empty, then return a new node */
        if (root == null) { 
            root = new Node(key); 
            return root; 
        } 

        /* Otherwise, recursively insert into the tree */
        if (key < root.key) {
            root.left = insertRec(root.left, key); 
        } else if (key > root.key) {
            root.right = insertRec(root.right, key); 
        } 

        return root; 
    }

    //Method to check if key is present
    public boolean contains(int key)
    {
        return containsRec(root, key);
    }

    // Helper function to hide the recursive logic
    public boolean containsRec(Node root, int key) {
        // Base case
        if (root == null) return false;

        // If the node has match with the given key
        if (root.key == key) return true;

        // Check left and right recursively
        return containsRec(root.left, key)
                || containsRec(root.right, key);
    } 
}

function tokenize(html) {
  const tokens = [];
  let token = '';
  for (let i = 0; i < html.length; i++) {
    const current = html[i];
    if (current === '<') {
      if (token !== '') tokens.push(token);
      token = '';
    } else if (current === '>') {
      tokens.push(token);
      token = '';
    } else {
      token += current;
    }
  }
  return tokens;
}

