def dfs_validate(root, lower_bound, upper_bound):
    if root is None:
        return True

    if root.val <= lower_bound or root.val >= upper_bound:
        return False

    if not dfs_validate(root.left, lower_bound, root.val):
        return False

    if not dfs_validate(root.right, root.val, upper_bound):
        return False

    return True

