function permute(arr) { 
    if (arr.length === 0) { 
        return []; 
    } else {
        let result = []; 
        for (let i = 0; i < arr.length; i++) { 
            let ch = arr.splice(i, 1); 
            let perm = permute(arr); 

            for (let j = 0; j < perm.length; j++) { 
                let x = perm[j].slice(0); 
