 int low = 0;
 int high = arr.length - 1;

 while(low <= high) {
 int mid = (low + high)/2;
 if(arr[mid].equals(target)) {
 return mid;
 }
 else if(arr[mid].compareTo(target) < 0) {
 low = mid + 1;
 }
 else {
 high = mid - 1;
 }
 }

 return -1;
}

