class Move:
    """
    Abstract Move class to be inherited by both Player Moves and Opponent Moves.
    It holds the basic info on the kind of move, its name, and what move it wins against.
    """

    def __init__(self, name):
        self.name = name

    def __str__(self):
        return self.name

    def beats(self, other):
        if other is None:
            return False
        return self.name in other.loses_to

class PlayerMove(Move):
    """
    The kinds of moves a player can use in a battle.
    """

    def __init__(self, name):
        super().__init__(name)
        self.loses_to = []

    def add_losing_options(self, *opponents):
        self.loses_to.extend(opponents)

class OpponentMove(Move):
    """
    The kinds of moves an opponent can use in a battle.
    """
    def __init__(self, name):
        super().__init__(name)
        self.beats = []

    def add_winning_options(self, *opponents):
        self.beats.extend(opponents)

