def longest_subsequence(s):
    n = len(s) 
    dp = [[0 for _ in range(n+1)] for _ in range(n+1)] 

    for i in range(1, n+1): 
        for j in range(1, n+1): 

            # If characters match and indices are
            # not same
            if (s[i-1] == s[j-1] and i != j):
                dp[i][j] =  1 + dp[i-1][j-1]   
            else: 
                dp[i][j] = max(dp[i][j-1], dp[i-1][j]); 

    # find index of maximum 
    max_len = 0
    max_index = 0
    for i in range(n+1): 
        if (max_len < dp[i][n]): 
            max_len = dp[i][n] 
            max_index = i 

    # If we have non-empty result, then insert 
    # all characters from first to last index  
    # of String 
    if (max_len > 0): 
        substr = ""
        for i in range(max_index - max_len+1, max_index+1): 
            substr += s[i] 
        return substr
    else:
        return ""

