Node* concatenate(Node* list1, Node* list2) {
    // If any of the list's head is null, return the other.
    if (!list1) return list2;
    if (!list2) return list1;

    Node* result = nullptr;
    Node* last = nullptr;

    // Initialize the result list
    if (list1->data < list2->data) {
        result = list1;
        last = list1;
        list1 = list1->next;
    } 
    else {
        result = list2;
        last = list2;
        list2 = list2->next;
    }

    // Keep iterate through both the lists and add the smaller element to the result list
    while (list1 && list2) {
        if (list1->data < list2->data) {
            last->next = list1;
            last = list1;
            list1 = list1->next;
        } else {
            last->next = list2;
            last = list2;
            list2 = list2->next;
        }
    }

    // Append the remaining elements of the list once iteration ends
    if (list1) last->next = list1;
    else last->next = list2;

    return result;
}

