def permute_letters(letters):
    if len(letters) == 0:
        return []

    if len(letters) == 1:
        return [letters]

    permuted_letters = []

    for letter in letters:
        remaining_letters = [letter2 for letter2 in letters if letter2 != letter]
        permutations = permute_letters(remaining_letters)

        for permutation in permutations:
            permuted_letters.append([letter] + permutation)

    return permuted_letters

class BinarySearchTree { 
    constructor(value) { 
        this.value = value;
        this.left = null;
        this.right = null;
    }

    addNode(value) {
        if (value < this.value) {
            this.left ? this.left.addNode(value) : this.left = new BinarySearchTree(value);
        } else if (value > this.value) {
            this.right ? this.right.addNode(value) : this.right = new BinarySearchTree(value);
        }
      }

    search(value) {
        if (value < this.value) {
            if (this.left) {
                return this.left.search(value);
            } 
        } else if (value > this.value) {
            if (this.right) {
                return this.right.search(value);
            }
        } else {
            return this;
        }
    }
}

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i-1
        while j >= 0 and key < arr[j]:
            arr[j+1] = arr[j]
            j -= 1
        arr[j+1] = key
    return arr

