def lowestCommonAncestor(root, p, q): 
    if (root is None or root.data == p or root.data == q): 
        return root  

    left = lowestCommonAncestor(root.left, p, q) 
    right = lowestCommonAncestor(root.right, p, q)

    if (left is not None and right is not None): 
        return root  

    if (left is None): 
        return right  
    else: 
        return left

