def caesar_cipher(message):
  new_message = ""

  for char in message:
    if char.isalpha():
      num = ord(char)
      num = num + 3
      if num > ord('z'):
        num -= 26
      new_message = new_message + chr(num)
    else:
      new_message = new_message + char

  return new_message

