def bubble_sort(lst):
    # Set swapped to True so the loop looks runs at least once
    swapped = True
    while swapped:
        swapped = False
        for i in range(len(lst) - 1):
            # If the current element is greater than the next element
            if lst[i] > lst[i + 1]:
                # Swap the two elements
                lst[i], lst[i + 1] = lst[i + 1], lst[i]
                # Set swapped to True so the loop runs again
                swapped = True

def sort_matrix(matrix):
  # Bubble sort algorithm
  nrows = len(matrix)
  ncols = len(matrix[0])
  for row in range(nrows):
    for col in range(ncols):
      for row2 in range(row+1, nrows):
        if matrix[row][col] > matrix[row2][col]:
            matrix[row][col], matrix[row2][col] = matrix[row2][col], matrix[row][col]
  return matrix

