            num_special_char += 1

    # if number of special characters is less than 3, generate new password
    if num_special_char < 3:
        return generate_password()

    return password

def longest_increasing_subsequence(arr):
    n = len(arr)
    lengths = [1] * n
    longest = 1
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lengths[i] < lengths[j] + 1:
                lengths[i] = lengths[j] + 1
                longest = max(longest, lengths[i])
    return longest

