def sum_divisors(n):
    '''Returns the sum of all divisors of the given number.'''
    if n <= 1:
        return 0
    #assume n is a positive integer
    sum_divisors = 1
    for i in range(2, int(n/2)+1):
        if n % i == 0:
            sum_divisors += i
    return sum_divisors

