def minCost(cost, m, n):

    # Create an array to store the results
    table = [[0 for x in range(n+1)] for x in range(m+1)] 

    # Initialize the base condition
    table[0][0] = cost[0][0] 
    for i in range(1, m+1): 
        table[i][0] = table[i-1][0] + cost[i][0] 

    for j in range(1, n+1): 
        table[0][j] = table[0][j-1] + cost[0][j] 

    # Apply cost recursion
    for i in range(1, m+1): 
        for j in range(1, n+1): 
            table[i][j] = min(table[i-1][j], table[i][j-1]) + cost[i][j] 

    # Return the result
    return table[m][n]

