class PriorityQueue:
    def __init__(self):
        self.data = []
        self.size = 0
        self.max_priority = 0

    def enqueue(self, item):
        self.data.append(item)
        self.size += 1
        self.max_priority += 1
        item.priority = self.max_priority

    def dequeue(self):
        if self.size == 0:
            return None
        min_item = self.data[0]
        min_index = 0
        for item in self.data[1:]:
            if item.priority < min_item.priority:
                min_item = item
                min_index = self.data.index(min_item)
        self.data.pop(min_index)
        self.size -= 1
        return min_item

def sortAlphabetically(strings): 
    for i in range(len(strings)-1): 
        for j in range(i+1, len(strings)): 
            if strings[i] > strings[j]: 
                temp = strings[i] 
                strings[i] = strings[j] 
                strings[j] = temp 
    return strings 

