fn quicksort(list: &mut [i32]) {
 if list.len() <= 1 {
  return;
 }

 let mut left_idx = 0;
 let mut right_idx = list.len() - 1;

 let pivot = list[right_idx];

 while left_idx < right_idx {
  while list[left_idx] < pivot {
   left_idx += 1;
  }

  while list[right_idx] > pivot {
   right_idx -= 1;
  }

  if left_idx != right_idx {
   list.swap(left_idx, right_idx);
  }
 }

 let new_pivot = right_idx;

 quicksort(&mut list[0..new_pivot]);
 quicksort(&mut list[(new_pivot + 1)..list.len()]);
}

function leastRepeatingCharacters(str) {
    const charFreqMap = {};
    let minFreqChar = null;
    let minFreq = Number.MAX_SAFE_INTEGER;

    Array.from(str).forEach(char => {
        if (!charFreqMap.hasOwnProperty(char)) {
            charFreqMap[char] = 0;
        }
        charFreqMap[char]++;
    });

    Object.keys(charFreqMap).forEach((char) => {
        if (charFreqMap[char] < minFreq) {
            minFreq = charFreqMap[char];
            minFreqChar = char;
        }
    });

    return minFreqChar;
}

